// Package k8seol is the upstream support of Kubernetes versions (D-91): the Kubernetes project's
// release table, built into each release, and what it says of a version: its minor's end of life,
// the maintenance mode before it, an estimate for a minor newer than the table, and a kubelet's
// version skew against its API server.
//
// The table is releases.json beside this file, generated by hack/k8seol (make k8s-eol) from
// kubernetes/website's data/releases/schedule.yaml and data/releases/eol.yaml (CC BY 4.0,
// ATTRIBUTION.md). The release pipeline runs the generator before it builds, so every release
// carries the table of its day, and keeps the committed table when the fetch fails. Cogpit never
// fetches it at run time. Only upstream's dates count (the owner, 2026-10-18): the support windows
// of managed services are not in it, and nothing here tells one distribution from another.
//
// Layer L0: no I/O; the table is embedded.
package k8seol

import (
	_ "embed" // the table
	"encoding/json"
	"errors"
	"fmt"
	"strconv"
	"strings"
	"sync"
	"time"
)

//go:embed releases.json
var embedded []byte

// DateLayout is how the table writes its dates.
const DateLayout = "2006-01-02"

// The estimate for a minor newer than the table (EstimateFrom): Kubernetes releases a minor about
// every four months, three a year, and every end of life since 1.19 lies near the 28th of the
// month fourteen months after its minor's release month (twelve months of support and two of
// maintenance mode, KEP-1498); the maintenance mode starts two months before it.
const (
	releaseStepMonths = 4
	supportMonths     = 14
	maintenanceMonths = 2
	estimateDay       = 28
)

// Minor is one minor release of the table, its dates as YYYY-MM-DD.
type Minor struct {
	// Minor is "1.36".
	Minor string `json:"minor"`
	// Released is the day of its .0 release; only the maintained minors' (schedule.yaml) have it.
	Released string `json:"released,omitempty"`
	// MaintenanceFrom is the day its maintenance mode starts (critical fixes only); only the
	// maintained minors' have it.
	MaintenanceFrom string `json:"maintenanceFrom,omitempty"`
	// EndOfLife is upstream's end of life.
	EndOfLife string `json:"endOfLife"`
	// FinalPatch is its last patch release; only the ended minors' (eol.yaml) have it.
	FinalPatch string `json:"finalPatch,omitempty"`
}

// Table is the release table: the minors in ascending order, without a gap, and the day it was
// fetched.
type Table struct {
	Source  string  `json:"source"`
	Fetched string  `json:"fetched"`
	Minors  []Minor `json:"minors"`
}

var (
	loadOnce sync.Once
	loaded   *Table
)

// Embedded returns the table built into this Cogpit. A table that does not parse would be an
// empty one, every version unknown; TestEmbeddedTable keeps that from shipping.
func Embedded() *Table {
	loadOnce.Do(func() {
		t, err := ParseTable(embedded)
		if err != nil {
			t = &Table{}
		}
		loaded = t
	})
	return loaded
}

// ParseTable reads a table and checks it (Validate).
func ParseTable(data []byte) (*Table, error) {
	var t Table
	if err := json.Unmarshal(data, &t); err != nil {
		return nil, fmt.Errorf("the release table does not parse: %w", err)
	}
	if err := t.Validate(); err != nil {
		return nil, err
	}
	return &t, nil
}

// ParseDate reads a table's date, midnight UTC.
func ParseDate(s string) (time.Time, error) { return time.Parse(DateLayout, s) }

// Validate checks what every table holds: the day it was fetched; minors of Kubernetes 1 in
// ascending order without a gap; every date a date; the ends of life in the minors' order; a
// minor's release before its maintenance mode, which is before its end of life, the end of life
// 12 to 18 months after the release (upstream's policy is 14, and 1.22 was extended to 16); and
// the newest minor's release day, which the estimate starts from.
func (t *Table) Validate() error {
	if _, err := ParseDate(t.Fetched); err != nil {
		return fmt.Errorf("the release table's fetch day %q: %w", t.Fetched, err)
	}
	if len(t.Minors) == 0 {
		return errors.New("the release table has no minors")
	}
	var prev Version
	var prevEOL time.Time
	for i, m := range t.Minors {
		v, ok := ParseVersion(m.Minor)
		if !ok || v.Major != 1 || v.String() != m.Minor {
			return fmt.Errorf("minor %q is not a minor of Kubernetes 1", m.Minor)
		}
		if i > 0 && v.Minor != prev.Minor+1 {
			return fmt.Errorf("minor %s follows %s: the minors must be in order without a gap", m.Minor, prev)
		}
		eol, err := ParseDate(m.EndOfLife)
		if err != nil {
			return fmt.Errorf("%s's end of life %q: %w", m.Minor, m.EndOfLife, err)
		}
		if i > 0 && eol.Before(prevEOL) {
			return fmt.Errorf("%s ends (%s) before %s (%s)", m.Minor, m.EndOfLife, prev, prevEOL.Format(DateLayout))
		}
		if err := m.checkDates(eol); err != nil {
			return err
		}
		prev, prevEOL = v, eol
	}
	if t.Minors[len(t.Minors)-1].Released == "" {
		return fmt.Errorf("the newest minor %s has no release day", prev)
	}
	return nil
}

// checkDates checks a minor's release and maintenance mode against its end of life.
func (m Minor) checkDates(eol time.Time) error {
	var rel time.Time
	if m.Released != "" {
		var err error
		if rel, err = ParseDate(m.Released); err != nil {
			return fmt.Errorf("%s's release %q: %w", m.Minor, m.Released, err)
		}
		if n := monthsBetween(rel, eol); n < 12 || n > 18 {
			return fmt.Errorf("%s ends %d months after its release (%s to %s); upstream's policy is 14", m.Minor, n, m.Released, m.EndOfLife)
		}
	}
	if m.MaintenanceFrom != "" {
		mt, err := ParseDate(m.MaintenanceFrom)
		if err != nil {
			return fmt.Errorf("%s's maintenance mode %q: %w", m.Minor, m.MaintenanceFrom, err)
		}
		if mt.After(eol) || (!rel.IsZero() && !mt.After(rel)) {
			return fmt.Errorf("%s's maintenance mode (%s) is not between its release and its end of life", m.Minor, m.MaintenanceFrom)
		}
	}
	return nil
}

// monthsBetween counts the calendar months from a's month to b's.
func monthsBetween(a, b time.Time) int {
	return (b.Year()-a.Year())*12 + int(b.Month()) - int(a.Month())
}

// Newest returns the table's newest minor; the zero Minor for an empty table.
func (t *Table) Newest() Minor {
	if len(t.Minors) == 0 {
		return Minor{}
	}
	return t.Minors[len(t.Minors)-1]
}

// Lookup returns a minor of the table.
func (t *Table) Lookup(v Version) (Minor, bool) {
	if len(t.Minors) == 0 || v.Major != 1 {
		return Minor{}, false
	}
	oldest, _ := ParseVersion(t.Minors[0].Minor)
	i := v.Minor - oldest.Minor
	if i < 0 || i >= len(t.Minors) {
		return Minor{}, false
	}
	return t.Minors[i], true
}

// Version is a Kubernetes version's major and minor.
type Version struct{ Major, Minor int }

// ParseVersion reads the major and minor of a version as the API server and the kubelet report
// it ("v1.36.1", "v1.34.2-gke.1234", "v1.31.4+k3s1") or of a minor ("1.36"); false when it holds
// none.
func ParseVersion(s string) (Version, bool) {
	s = strings.TrimPrefix(strings.TrimSpace(s), "v")
	major, rest, ok := strings.Cut(s, ".")
	if !ok {
		return Version{}, false
	}
	end := strings.IndexFunc(rest, func(r rune) bool { return r < '0' || r > '9' })
	if end < 0 {
		end = len(rest)
	}
	ma, err1 := strconv.Atoi(major)
	mi, err2 := strconv.Atoi(rest[:end])
	if err1 != nil || err2 != nil || end == 0 || ma < 0 || mi < 0 {
		return Version{}, false
	}
	return Version{Major: ma, Minor: mi}, true
}

// String writes the minor: "1.36".
func (v Version) String() string { return strconv.Itoa(v.Major) + "." + strconv.Itoa(v.Minor) }

// State is a version's upstream support on a day.
type State string

// States.
const (
	// Unknown: the version holds no minor of Kubernetes 1, or the table is empty.
	Unknown State = "unknown"
	// Supported: before the minor's maintenance mode.
	Supported State = "supported"
	// Maintenance: the minor's last two months before its end of life, critical fixes only; the
	// window marks it softly.
	Maintenance State = "maintenance"
	// EndOfLife: past the minor's end of life; the window marks it ⚠.
	EndOfLife State = "endOfLife"
)

// Support is what the table says of a version's minor.
type Support struct {
	// Minor is the version's minor, "1.36"; empty when the version holds none.
	Minor string `json:"minor,omitempty"`
	// Released, MaintenanceFrom and EndOfLife are the minor's days, YYYY-MM-DD, as far as known.
	Released        string `json:"released,omitempty"`
	MaintenanceFrom string `json:"maintenanceFrom,omitempty"`
	EndOfLife       string `json:"endOfLife,omitempty"`
	// Estimated is set for a minor newer than the table: its days follow the rule (EstimateFrom),
	// accurate to weeks.
	Estimated bool `json:"estimated,omitempty"`
	// Before is set for a minor older than the table's oldest: its end of life lies before
	// EndOfLife, the oldest's.
	Before bool `json:"before,omitempty"`
	// TableNewest is the table's newest minor, TableFetched the day the table was fetched.
	TableNewest  string `json:"tableNewest,omitempty"`
	TableFetched string `json:"tableFetched,omitempty"`
}

// SupportOf returns what the embedded table says of a version.
func SupportOf(version string) Support { return Embedded().SupportOf(version) }

// SupportOf returns what the table says of a version: its minor's days, estimated for a minor
// newer than the table.
func (t *Table) SupportOf(version string) Support {
	s := Support{TableNewest: t.Newest().Minor, TableFetched: t.Fetched}
	v, ok := ParseVersion(version)
	if !ok || v.Major != 1 || len(t.Minors) == 0 {
		return s
	}
	s.Minor = v.String()
	oldest, _ := ParseVersion(t.Minors[0].Minor)
	newest, _ := ParseVersion(t.Newest().Minor)
	switch {
	case v.Minor < oldest.Minor:
		s.EndOfLife, s.Before = t.Minors[0].EndOfLife, true
	case v.Minor > newest.Minor:
		rel, mt, eol, ok := EstimateFrom(t.Newest(), v.Minor-newest.Minor)
		if !ok {
			s.Minor = ""
			return s
		}
		s.Released, s.MaintenanceFrom, s.EndOfLife = rel.Format(DateLayout), mt.Format(DateLayout), eol.Format(DateLayout)
		s.Estimated = true
	default:
		m, _ := t.Lookup(v)
		s.Released, s.MaintenanceFrom, s.EndOfLife = m.Released, m.MaintenanceFrom, m.EndOfLife
	}
	return s
}

// EstimateFrom estimates the days of the minor ahead minors after a known one, from the known
// minor's release day: its release ahead × 4 months later (the first of that month), its end of
// life on the 28th of the month 14 months after that, its maintenance mode two months before. ok
// is false when the known minor has no release day.
func EstimateFrom(known Minor, ahead int) (released, maintenance, endOfLife time.Time, ok bool) {
	rel, err := ParseDate(known.Released)
	if err != nil {
		return time.Time{}, time.Time{}, time.Time{}, false
	}
	released = time.Date(rel.Year(), rel.Month()+time.Month(releaseStepMonths*ahead), 1, 0, 0, 0, 0, time.UTC)
	endOfLife = time.Date(released.Year(), released.Month()+supportMonths, estimateDay, 0, 0, 0, 0, time.UTC)
	maintenance = time.Date(endOfLife.Year(), endOfLife.Month()-maintenanceMonths, estimateDay, 0, 0, 0, 0, time.UTC)
	return released, maintenance, endOfLife, true
}

// day is a time's calendar day in its own zone, as midnight UTC (the table's dates are days).
func day(t time.Time) time.Time {
	y, m, d := t.Date()
	return time.Date(y, m, d, 0, 0, 0, 0, time.UTC)
}

// EndOfLifeDay returns the end of life as a day (midnight UTC); false when it is not known.
func (s Support) EndOfLifeDay() (time.Time, bool) {
	if s.Minor == "" {
		return time.Time{}, false
	}
	t, err := ParseDate(s.EndOfLife)
	return t, err == nil
}

// DaysLeft counts the days from now's day (in now's zone) to the end of life: 0 on its day,
// negative past it, 0 when it is not known.
func (s Support) DaysLeft(now time.Time) int {
	eol, ok := s.EndOfLifeDay()
	if !ok {
		return 0
	}
	return int(eol.Sub(day(now)).Hours() / 24)
}

// StateAt returns the support on now's day, in now's zone: the end of life's day itself still
// counts as supported.
func (s Support) StateAt(now time.Time) State {
	eol, ok := s.EndOfLifeDay()
	switch {
	case !ok:
		return Unknown
	case s.Before || day(now).After(eol):
		return EndOfLife
	}
	if mt, err := ParseDate(s.MaintenanceFrom); err == nil && !day(now).Before(mt) {
		return Maintenance
	}
	return Supported
}

// Text is the support as a tooltip says it, on now's day, the dates written by date: "Upstream
// support until 28.06.2027 (253 days)", "Upstream support until 27.10.2026 (9 days), maintenance
// mode since 27.08.2026", "Upstream end of life since 11.11.2025", with "about" and ", estimated:
// this Cogpit's table ends at 1.37" for an estimate; "No upstream support dates for this version"
// when there are none.
func (s Support) Text(now time.Time, date func(time.Time) string) string {
	switch s.StateAt(now) {
	case Unknown:
		return "No upstream support dates for this version"
	case EndOfLife:
		return "Upstream end of life since " + s.Short(now, date)[len("ended "):]
	}
	return "Upstream support " + s.Short(now, date)
}

// Short is the support as the node drawer's "Upstream support" says it: "until 28.06.2027 (253
// days)", "until 27.10.2026 (9 days), maintenance mode since 27.08.2026", "ended 11.11.2025",
// "ended before 23.10.2016", with "about" and ", estimated: this Cogpit's table ends at 1.37" for
// an estimate; "unknown" when there are none.
func (s Support) Short(now time.Time, date func(time.Time) string) string {
	eol, ok := s.EndOfLifeDay()
	about := ""
	if s.Estimated {
		about = "about "
	}
	var out string
	switch st := s.StateAt(now); {
	case !ok:
		return "unknown"
	case st == EndOfLife && s.Before:
		out = "ended before " + date(eol)
	case st == EndOfLife:
		out = "ended " + about + date(eol)
	default:
		out = "until " + about + date(eol) + " (" + daysText(s.DaysLeft(now)) + ")"
		if mt, err := ParseDate(s.MaintenanceFrom); err == nil && st == Maintenance {
			out += ", maintenance mode since " + about + date(mt)
		}
	}
	if s.Estimated {
		out += ", estimated: this Cogpit's table ends at " + s.TableNewest
	}
	return out
}

// daysText writes the days left: "today", "1 day", "253 days".
func daysText(n int) string {
	switch n {
	case 0:
		return "today"
	case 1:
		return "1 day"
	}
	return strconv.Itoa(n) + " days"
}

// Skew is a kubelet's version against its API server's, by Kubernetes' version skew policy
// (kubelet): never newer than the API server, at most three minors older, two for a kubelet older
// than 1.25.
type Skew struct {
	Kubelet, Server Version
	// Newer is set when the kubelet is newer than the API server.
	Newer bool
	// Behind counts the minors the kubelet is behind the API server; 0 when it is not.
	Behind int
	// Allowed is how many minors behind the policy allows for this kubelet.
	Allowed int
}

// KubeletSkew compares a kubelet's version with its API server's; false when either holds no
// minor of Kubernetes 1.
func KubeletSkew(kubelet, server string) (Skew, bool) {
	k, ok1 := ParseVersion(kubelet)
	s, ok2 := ParseVersion(server)
	if !ok1 || !ok2 || k.Major != 1 || s.Major != 1 {
		return Skew{}, false
	}
	out := Skew{Kubelet: k, Server: s, Allowed: 3}
	if k.Minor < 25 {
		out.Allowed = 2
	}
	switch {
	case k.Minor > s.Minor:
		out.Newer = true
	default:
		out.Behind = s.Minor - k.Minor
	}
	return out, true
}

// Outside reports whether the policy does not allow the pair.
func (k Skew) Outside() bool { return k.Newer || k.Behind > k.Allowed }

// Text says how the pair falls outside the policy: "Kubelet 1.37 is newer than the API server
// 1.36: outside the version skew policy", "Kubelet 1.31 is 4 minors behind the API server 1.35:
// the version skew policy allows 3"; "" inside it.
func (k Skew) Text() string {
	switch {
	case k.Newer:
		return "Kubelet " + k.Kubelet.String() + " is newer than the API server " + k.Server.String() + ": outside the version skew policy"
	case k.Behind > k.Allowed:
		return "Kubelet " + k.Kubelet.String() + " is " + strconv.Itoa(k.Behind) + " minors behind the API server " + k.Server.String() +
			": the version skew policy allows " + strconv.Itoa(k.Allowed)
	}
	return ""
}

// Short says it as the node drawer's "Version skew" does, beside the kubelet's version: "newer
// than the API server 1.36", "4 minors behind the API server 1.35, the policy allows 3"; "" inside
// the policy.
func (k Skew) Short() string {
	switch {
	case k.Newer:
		return "newer than the API server " + k.Server.String()
	case k.Behind > k.Allowed:
		return strconv.Itoa(k.Behind) + " minors behind the API server " + k.Server.String() + ", the policy allows " + strconv.Itoa(k.Allowed)
	}
	return ""
}
